context_title:
domain FLOAT {
  function real value(f: FLOAT): real
  function FLOAT from_real(r: real): FLOAT
  function real sqrt_real(r: real): real
  function real clamp_real(r: real, min: real, max: real): real
  function real f32_to_real(f: FLOAT): real
  function FLOAT real_to_f32(r: real): FLOAT
  function bool is_nan(f: FLOAT): bool
  function bool is_inf(f: FLOAT): bool
}

domain UINT64 {
  function int value(u: UINT64): int
  function UINT64 from_int(i: int): UINT64
  function UINT64 xor(a: UINT64, b: UINT64): UINT64
  function UINT64 mul(a: UINT64, b: UINT64): UINT64
  function UINT64 add(a: UINT64, b: UINT64): UINT64
  function UINT64 min(a: UINT64, b: UINT64): UINT64
  function int popcount(a: UINT64): int
  function int clamped_to_int(u: UINT64): int
}

domain UINT32 {
  function int value(u: UINT32): int
  function UINT32 from_int(i: int): UINT32
}

domain USIZE {
  function int value(u: USIZE): int
  function USIZE from_int(i: int): USIZE
}

function stableHash(data: Seq[int], seed: UINT64): UINT64

domain RANKERCONFIG {
  const STREAMING_BUFFER_SIZE: int
  const STREAMING_WINDOW_SIZE: int
  const DEFAULT_TOP_K_RETRIEVAL: int
  const HASH_SEED_MULTIPLIER_A: UINT64
  const HASH_SEED_MULTIPLIER_B: UINT64
  const LEARNING_RATE: FLOAT
  const DIVERSITY_WEIGHT: FLOAT
  const PROXIMITY_WEIGHT: FLOAT
  const MAX_RAW_SCORE: FLOAT
  const BASE_SCORE_WEIGHT: FLOAT
  const OVERLAP_WEIGHT: FLOAT
  const JACCARD_WEIGHT: FLOAT
}

field ngram_weights: Seq[FLOAT]
field lsh_hash_params: Seq[UINT64]
field num_hash_functions: int
field num_ngrams: int
field seed: UINT64
field allocator: Ref
field bits: Seq[UINT64]
field len: int
field data: Seq[FLOAT]
field shape: Seq[int]
field tokens: Seq[UINT32]
field score: FLOAT
field position: UINT64
field anchor: bool
field map_data: Seq[Option[UINT32]]

predicate valid_allocator(alloc: Ref) {
  acc(alloc)
}

predicate valid_float_slice(s: Seq[FLOAT]) {
  true
}

predicate valid_u64_slice(s: Seq[UINT64]) {
  true
}

predicate valid_u32_slice(s: Seq[UINT32]) {
  true
}

predicate valid_int_slice(s: Seq[int]) {
  true
}

predicate valid_ranked_segment(rs: Ref) {
  acc(rs.tokens, read) && valid_u32_slice(rs.tokens) &&
  acc(rs.score, read) &&
  acc(rs.position, read) &&
  acc(rs.anchor, read)
}

predicate valid_ranked_segment_write(rs: Ref) {
  acc(rs.tokens) && valid_u32_slice(rs.tokens) &&
  acc(rs.score) &&
  acc(rs.position) &&
  acc(rs.anchor)
}

predicate valid_ssi(ssi: Ref) {
  acc(ssi.map_data, read)
}

predicate valid_tensor(t: Ref) {
  acc(t.data, read) && valid_float_slice(t.data) &&
  acc(t.shape, read) && valid_int_slice(t.shape)
}

predicate valid_bitset(bs: Ref) {
  acc(bs.bits, read) && valid_u64_slice(bs.bits) &&
  acc(bs.len, read)
}

predicate valid_ranker(self: Ref) {
  acc(self.ngram_weights, read) && valid_float_slice(self.ngram_weights) &&
  acc(self.lsh_hash_params, read) && valid_u64_slice(self.lsh_hash_params) &&
  acc(self.num_hash_functions, read) &&
  acc(self.num_ngrams, read) &&
  acc(self.seed, read) &&
  acc(self.allocator, read)
}

predicate valid_ranker_write(self: Ref) {
  acc(self.ngram_weights) && valid_float_slice(self.ngram_weights) &&
  acc(self.lsh_hash_params) && valid_u64_slice(self.lsh_hash_params) &&
  acc(self.num_hash_functions) &&
  acc(self.num_ngrams) &&
  acc(self.seed) &&
  acc(self.allocator)
}

