method Ranker_init(allocator: Ref, num_ngrams: int, num_hash_funcs: int, seed: UINT64) returns (self: Ref)
  requires valid_allocator(allocator)
  requires num_ngrams > 0
  requires num_hash_funcs > 0
  ensures valid_ranker_write(self)
  ensures self.num_ngrams == num_ngrams
  ensures self.num_hash_functions == num_hash_funcs
  ensures self.seed == seed
  ensures len(self.ngram_weights) == num_ngrams
  ensures len(self.lsh_hash_params) == num_hash_funcs * 2
{
  self := new(ngram_weights, lsh_hash_params, num_hash_functions, num_ngrams, seed, allocator);

  var weights: Seq[FLOAT] := alloc_f32(allocator, num_ngrams);
  self.ngram_weights := weights;

  var i: int := 0;
  while (i < num_ngrams)
    invariant 0 <= i && i <= num_ngrams
    invariant valid_float_slice(self.ngram_weights)
    invariant len(self.ngram_weights) == num_ngrams
  {
    var decay_val: real := 1.0 / (i + 1);
    self.ngram_weights[i] := FLOAT_from_real(decay_val);
    i := i + 1;
  }

  var hash_params: Seq[UINT64] := alloc_u64(allocator, num_hash_funcs * 2);
  self.lsh_hash_params := hash_params;

  i := 0;
  while (i < num_hash_funcs)
    invariant 0 <= i && i <= num_hash_funcs
    invariant valid_u64_slice(self.lsh_hash_params)
    invariant len(self.lsh_hash_params) == num_hash_funcs * 2
  {
    var i_u64: UINT64 := UINT64_from_int(i);
    var i_plus_one: UINT64 := UINT64_from_int(i + 1);
    var mul_a: UINT64 := UINT64_mul(i_u64, RANKERCONFIG_HASH_SEED_MULTIPLIER_A);
    var mul_b: UINT64 := UINT64_mul(i_plus_one, RANKERCONFIG_HASH_SEED_MULTIPLIER_B);
    self.lsh_hash_params[i * 2] := UINT64_add(seed, mul_a);
    self.lsh_hash_params[i * 2 + 1] := UINT64_add(seed, mul_b);
    i := i + 1;
  }

  self.num_hash_functions := num_hash_funcs;
  self.num_ngrams := num_ngrams;
  self.seed := seed;
  self.allocator := allocator;
}

method Ranker_deinit(self: Ref)
  requires valid_ranker_write(self)
  ensures !valid_ranker_write(self)
{
  free_f32(self.allocator, self.ngram_weights);
  free_u64(self.allocator, self.lsh_hash_params);
}

method Ranker_scoreSequence(self: Ref, tokens: Seq[UINT32], ssi: Ref) returns (raw_score: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  requires valid_ssi(ssi)
  ensures valid_float_slice(raw_score)
{
  if (len(tokens) == 0) {
    raw_score := FLOAT_from_real(0.0);
    return;
  }

  var ngram_score: FLOAT := FLOAT_from_real(0.0);
  var gram: int := 1;
  var limit: int := min(self.num_ngrams, len(tokens) + 1);

  while (gram < limit)
    invariant 1 <= gram && gram <= limit
    invariant valid_float_slice(ngram_score)
  {
    if (len(tokens) < gram) {
      gram := gram + 1;
      continue;
    }

    var start: int := 0;
    var end: int := len(tokens) - gram + 1;
    while (start < end)
      invariant 0 <= start && start <= end
      invariant valid_float_slice(ngram_score)
    {
      var ngram: Seq[UINT32] := tokens[start .. start + gram];
      var h: UINT64 := stableHash(ngram, self.seed);
      var s: Ref := ssi_getSegment(ssi, h);

      var weight_idx: int := min(gram - 1, len(self.ngram_weights) - 1);
      var ws: FLOAT := self.ngram_weights[weight_idx];
      var ss: FLOAT := s.score;
      ngram_score := FLOAT_from_real(FLOAT_value(ngram_score) + FLOAT_value(ws) * FLOAT_value(ss));

      start := start + 1;
    }
    gram := gram + 1;
  }

  var diversity_score: FLOAT := Ranker_computeTokenDiversity(self, tokens);
  var proximity: FLOAT := Ranker_anchorProximity(self, tokens, ssi);

  var raw_val: real := FLOAT_value(ngram_score) + FLOAT_value(RANKERCONFIG_DIVERSITY_WEIGHT) * FLOAT_value(diversity_score) + FLOAT_value(RANKERCONFIG_PROXIMITY_WEIGHT) * FLOAT_value(proximity);
  raw_val := clamp_real(raw_val, 0.0, FLOAT_value(RANKERCONFIG_MAX_RAW_SCORE));
  raw_score := FLOAT_from_real(raw_val / FLOAT_value(RANKERCONFIG_MAX_RAW_SCORE));
}

method Ranker_computeTokenDiversity(self: Ref, tokens: Seq[UINT32]) returns (diversity: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  ensures valid_float_slice(diversity)
{
  if (len(tokens) == 0) {
    diversity := FLOAT_from_real(0.0);
    return;
  }

  var unique_tokens: Ref := hashmap_u32_init(self.allocator);

  var i: int := 0;
  while (i < len(tokens))
    invariant 0 <= i && i <= len(tokens)
    invariant acc(unique_tokens.map_data)
  {
    hashmap_u32_put(unique_tokens, tokens[i], 0);
    i := i + 1;
  }

  var unique_count: int := hashmap_u32_count(unique_tokens);
  var div_val: real := unique_count / len(tokens);
  diversity := FLOAT_from_real(div_val);

  hashmap_u32_deinit(unique_tokens);
}

method Ranker_anchorProximity(self: Ref, tokens: Seq[UINT32], ssi: Ref) returns (prox: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  requires valid_ssi(ssi)
  ensures valid_float_slice(prox)
{
  if (len(tokens) == 0) {
    prox := FLOAT_from_real(0.0);
    return;
  }

  var anchors: int := 0;
  var total_dist: real := 0.0;
  var i: int := 0;

  while (i < len(tokens))
    invariant 0 <= i && i <= len(tokens)
    invariant anchors >= 0
  {
    var pos: UINT64 := UINT64_from_int(i);
    var s: Ref := ssi_getSegment(ssi, pos);

    if (UINT64_value(s.anchor_hash) != 0) {
      anchors := anchors + 1;
      var i_u64: UINT64 := UINT64_from_int(i);
      var s_pos: UINT64 := s.position;
      var raw_dist: UINT64 := UINT64_min(i_u64, s_pos); 
      raw_dist := UINT64_add(raw_dist, UINT64_min(i_u64, s_pos));

      var dist_f: real := UINT64_clamped_to_int(raw_dist);
      total_dist := total_dist + dist_f;
    }
    i := i + 1;
  }

  if (anchors == 0) {
    prox := FLOAT_from_real(0.0);
    return;
  }

  var denominator: int := anchors * len(tokens);
  var denom_clamped: int := min(denominator, 2147483647);
  var denom_f: real := max(denom_clamped, 1);
  var res: real := 1.0 - clamp_real(total_dist / denom_f, 0.0, 1.0);
  prox := FLOAT_from_real(res);
}

method Ranker_computeTokenOverlap(self: Ref, tokens: Seq[UINT32], query: Seq[UINT32]) returns (overlap: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  requires valid_u32_slice(query)
  ensures valid_float_slice(overlap)
{
  if (len(tokens) == 0 || len(query) == 0) {
    overlap := FLOAT_from_real(0.0);
    return;
  }

  var overlap_count: int := 0;
  var i: int := 0;
  while (i < len(tokens))
    invariant 0 <= i && i <= len(tokens)
    invariant overlap_count >= 0
  {
    var j: int := 0;
    var found: bool := false;
    while (j < len(query) && !found)
      invariant 0 <= j && j <= len(query)
    {
      if (UINT32_value(tokens[i]) == UINT32_value(query[j])) {
        found := true;
      }
      j := j + 1;
    }
    if (found) {
      overlap_count := overlap_count + 1;
    }
    i := i + 1;
  }

  var max_len: int := max(len(tokens), len(query));
  overlap := FLOAT_from_real(overlap_count / max_len);
}

method Ranker_computeJaccardSimilarity(self: Ref, tokens: Seq[UINT32], query: Seq[UINT32]) returns (jaccard: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  requires valid_u32_slice(query)
  ensures valid_float_slice(jaccard)
{
  if (len(tokens) == 0 && len(query) == 0) {
    jaccard := FLOAT_from_real(1.0);
    return;
  }
  if (len(tokens) == 0 || len(query) == 0) {
    jaccard := FLOAT_from_real(0.0);
    return;
  }

  var seen: Ref := hashmap_u32_init(self.allocator);

  var i: int := 0;
  while (i < len(tokens))
    invariant 0 <= i && i <= len(tokens)
    invariant acc(seen.map_data)
  {
    hashmap_u32_put(seen, tokens[i], 1);
    i := i + 1;
  }

  i := 0;
  while (i < len(query))
    invariant 0 <= i && i <= len(query)
    invariant acc(seen.map_data)
  {
    var val: int := 0;
    var found: bool := false;
    val, found := hashmap_u32_get(seen, query[i]);
    if (found) {
      if (val == 1) {
        hashmap_u32_put(seen, query[i], 2);
      }
    } else {
      hashmap_u32_put(seen, query[i], 1);
    }
    i := i + 1;
  }

  var intersection: int := 0;
  var union_size: int := 0;

  var it: Ref := hashmap_u32_iterator_init(seen);
  var k: UINT32 := UINT32_from_int(0);
  var v: int := 0;
  var has_next: bool := true;

  while (has_next)
    invariant acc(seen.map_data, read)
  {
    k, v, has_next := hashmap_u32_iterator_next(it, seen);
    if (has_next) {
      union_size := union_size + 1;
      if (v == 2) {
        intersection := intersection + 1;
      }
    }
  }

  hashmap_u32_deinit(seen);

  if (union_size == 0) {
    jaccard := FLOAT_from_real(0.0);
    return;
  }
  jaccard := FLOAT_from_real(intersection / union_size);
}

method Ranker_scoreSequenceWithQuery(self: Ref, tokens: Seq[UINT32], query: Seq[UINT32], ssi: Ref) returns (score: FLOAT)
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  requires valid_u32_slice(query)
  requires valid_ssi(ssi)
  ensures valid_float_slice(score)
{
  var base_score: FLOAT := Ranker_scoreSequence(self, tokens, ssi);
  var token_overlap: FLOAT := Ranker_computeTokenOverlap(self, tokens, query);
  var jaccard: FLOAT := Ranker_computeJaccardSimilarity(self, tokens, query);

  var combined: real := FLOAT_value(base_score) * FLOAT_value(RANKERCONFIG_BASE_SCORE_WEIGHT) + FLOAT_value(token_overlap) * FLOAT_value(RANKERCONFIG_OVERLAP_WEIGHT) + FLOAT_value(jaccard) * FLOAT_value(RANKERCONFIG_JACCARD_WEIGHT);
  combined := clamp_real(combined, 0.0, 1.0);
  score := FLOAT_from_real(combined);
}

method Ranker_rankCandidates(self: Ref, candidates: Seq[Ref], ssi: Ref, allocator: Ref)
  requires valid_ranker(self)
  requires forall i: int :: 0 <= i && i < len(candidates) ==> valid_ranked_segment_write(candidates[i])
  requires valid_ssi(ssi)
  requires valid_allocator(allocator)
{
  if (len(candidates) == 0) { return; }

  var scores: Seq[FLOAT] := alloc_f32(allocator, len(candidates));

  var i: int := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
    invariant valid_float_slice(scores)
    invariant len(scores) == len(candidates)
  {
    scores[i] := Ranker_scoreSequence(self, candidates[i].tokens, ssi);
    i := i + 1;
  }

  normalizeScoresStatic(scores);

  var indices: Seq[int] := alloc_int(allocator, len(candidates));

  i := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
    invariant valid_int_slice(indices)
  {
    indices[i] := i;
    i := i + 1;
  }

  indices := sort_indices(indices, scores);

  var sorted_tokens: Seq[Seq[UINT32]] := alloc_u32_array(allocator, len(candidates)); 
  var sorted_scores: Seq[FLOAT] := alloc_f32(allocator, len(candidates));
  var sorted_positions: Seq[UINT64] := alloc_u64(allocator, len(candidates));
  var sorted_anchors: Seq[bool] := alloc_bool_array(allocator, len(candidates));

  i := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
  {
    var src_idx: int := indices[i];
    sorted_tokens[i] := dupe_u32(allocator, candidates[src_idx].tokens);
    sorted_scores[i] := scores[src_idx];
    sorted_positions[i] := candidates[src_idx].position;
    sorted_anchors[i] := candidates[src_idx].anchor;
    i := i + 1;
  }

  i := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
  {
    free_u32(allocator, candidates[i].tokens);
    candidates[i].tokens := sorted_tokens[i];
    candidates[i].score := sorted_scores[i];
    candidates[i].position := sorted_positions[i];
    candidates[i].anchor := sorted_anchors[i];
    i := i + 1;
  }

  free_f32(allocator, scores);
  free_int(allocator, indices);
}

method normalizeScoresStatic(scores: Seq[FLOAT])
  requires valid_float_slice(scores)
{
  if (len(scores) == 0) { return; }

  var min_score: FLOAT := FLOAT_from_real(1.0 / 0.0);
  var max_score: FLOAT := FLOAT_from_real(-1.0 / 0.0);
  var valid_count: int := 0;

  var i: int := 0;
  while (i < len(scores))
    invariant 0 <= i && i <= len(scores)
    invariant valid_float_slice(min_score)
    invariant valid_float_slice(max_score)
  {
    var s: FLOAT := scores[i];
    if (!FLOAT_is_nan(s) && !FLOAT_is_inf(s)) {
      valid_count := valid_count + 1;
      if (FLOAT_value(s) < FLOAT_value(min_score)) { min_score := s; }
      if (FLOAT_value(s) > FLOAT_value(max_score)) { max_score := s; }
    }
    i := i + 1;
  }

  if (valid_count == 0) { return; }

  if (FLOAT_value(max_score) == FLOAT_value(min_score)) {
    i := 0;
    while (i < len(scores))
      invariant 0 <= i && i <= len(scores)
    {
      if (!FLOAT_is_nan(scores[i]) && !FLOAT_is_inf(scores[i])) {
        scores[i] := FLOAT_from_real(0.5);
      }
      i := i + 1;
    }
    return;
  }

  var range: real := FLOAT_value(max_score) - FLOAT_value(min_score);
  i := 0;
  while (i < len(scores))
    invariant 0 <= i && i <= len(scores)
  {
    if (!FLOAT_is_nan(scores[i]) && !FLOAT_is_inf(scores[i])) {
      scores[i] := FLOAT_from_real((FLOAT_value(scores[i]) - FLOAT_value(min_score)) / range);
    }
    i := i + 1;
  }
}

method Ranker_updateWeights(self: Ref, gradients: Seq[FLOAT])
  requires valid_ranker_write(self)
  requires valid_float_slice(gradients)
{
  var i: int := 0;
  var limit: int := min(len(self.ngram_weights), len(gradients));
  while (i < limit)
    invariant 0 <= i && i <= limit
    invariant valid_float_slice(self.ngram_weights)
  {
    var grad: FLOAT := gradients[i];
    if (!FLOAT_is_nan(grad) && !FLOAT_is_inf(grad)) {
      var w: real := FLOAT_value(self.ngram_weights[i]);
      var g: real := FLOAT_value(grad);
      var lr: real := FLOAT_value(RANKERCONFIG_LEARNING_RATE);
      var new_val: real := clamp_real(w + g * lr, 0.0, 1.0);
      self.ngram_weights[i] := FLOAT_from_real(new_val);
    }
    i := i + 1;
  }
}

method Ranker_minHashSignature(self: Ref, tokens: Seq[UINT32]) returns (sig: Seq[UINT64])
  requires valid_ranker(self)
  requires valid_u32_slice(tokens)
  ensures valid_u64_slice(sig)
  ensures len(sig) == self.num_hash_functions
{
  if (len(tokens) == 0) {
    sig := alloc_u64(self.allocator, self.num_hash_functions);
    var i: int := 0;
    while (i < len(sig))
      invariant 0 <= i && i <= len(sig)
    {
      sig[i] := UINT64_from_int(-1);
      i := i + 1;
    }
    return;
  }

  sig := alloc_u64(self.allocator, self.num_hash_functions);

  var h: int := 0;
  while (h < self.num_hash_functions)
    invariant 0 <= h && h <= self.num_hash_functions
    invariant valid_u64_slice(sig)
    invariant len(sig) == self.num_hash_functions
  {
    var min_hash: UINT64 := UINT64_from_int(-1);
    var seed_a: UINT64 := self.lsh_hash_params[h * 2];
    var seed_b: UINT64 := self.lsh_hash_params[h * 2 + 1];

    var i: int := 0;
    while (i < len(tokens))
      invariant 0 <= i && i <= len(tokens)
    {
      var token_bytes: Seq[int] := seq(1, UINT32_value(tokens[i])); 
      var hash_val: UINT64 := UINT64_xor(stableHash(token_bytes, seed_a), seed_b);
      if (UINT64_value(hash_val) < UINT64_value(min_hash)) {
        min_hash := hash_val;
      }
      i := i + 1;
    }
    sig[h] := min_hash;
    h := h + 1;
  }
}

method Ranker_jaccardSimilarityFromSignatures(sig1: Seq[UINT64], sig2: Seq[UINT64]) returns (sim: FLOAT)
  requires valid_u64_slice(sig1)
  requires valid_u64_slice(sig2)
  ensures valid_float_slice(sim)
{
  if (len(sig1) != len(sig2)) {
    sim := FLOAT_from_real(0.0);
    return;
  }
  if (len(sig1) == 0) {
    sim := FLOAT_from_real(0.0);
    return;
  }

  var matches: int := 0;
  var i: int := 0;
  while (i < len(sig1))
    invariant 0 <= i && i <= len(sig1)
    invariant matches >= 0
  {
    if (UINT64_value(sig1[i]) == UINT64_value(sig2[i])) {
      matches := matches + 1;
    }
    i := i + 1;
  }
  sim := FLOAT_from_real(matches / len(sig1));
}

method Ranker_estimateJaccard(set1: Ref, set2: Ref) returns (est: FLOAT)
  requires valid_bitset(set1)
  requires valid_bitset(set2)
  ensures valid_float_slice(est)
{
  var intersect: int := 0;
  var union_count: int := 0;
  var words: int := min(len(set1.bits), len(set2.bits));

  var i: int := 0;
  while (i < words)
    invariant 0 <= i && i <= words
  {
    var b1: UINT64 := set1.bits[i];
    var b2: UINT64 := set2.bits[i];
    intersect := intersect + UINT64_popcount(UINT64_and(b1, b2));
    union_count := union_count + UINT64_popcount(UINT64_or(b1, b2));
    i := i + 1;
  }

  if (union_count == 0) {
    est := FLOAT_from_real(0.0);
  } else {
    est := FLOAT_from_real(intersect / union_count);
  }
}

method Ranker_vectorScore(embedding: Ref, query_emb: Ref) returns (score: FLOAT)
  requires valid_tensor(embedding)
  requires valid_tensor(query_emb)
  ensures valid_float_slice(score)
{
  if (len(embedding.shape) != len(query_emb.shape)) {
    score := FLOAT_from_real(0.0); 
    return;
  }

  var shape_match: bool := true;
  var i: int := 0;
  while (i < len(embedding.shape))
    invariant 0 <= i && i <= len(embedding.shape)
  {
    if (embedding.shape[i] != query_emb.shape[i]) {
      shape_match := false;
    }
    i := i + 1;
  }

  if (!shape_match) {
    score := FLOAT_from_real(0.0);
    return;
  }

  if (len(embedding.data) == 0) {
    score := FLOAT_from_real(0.0);
    return;
  }

  var dot_prod: real := 0.0;
  var norm_emb: real := 0.0;
  var norm_query: real := 0.0;

  i := 0;
  while (i < len(embedding.data))
    invariant 0 <= i && i <= len(embedding.data)
  {
    var e: FLOAT := embedding.data[i];
    var q: FLOAT := query_emb.data[i];

    if (!FLOAT_is_nan(e) && !FLOAT_is_nan(q) && !FLOAT_is_inf(e) && !FLOAT_is_inf(q)) {
      dot_prod := dot_prod + FLOAT_value(e) * FLOAT_value(q);
      norm_emb := norm_emb + FLOAT_value(e) * FLOAT_value(e);
      norm_query := norm_query + FLOAT_value(q) * FLOAT_value(q);
    }
    i := i + 1;
  }

  if (norm_emb <= 0.0 || norm_query <= 0.0) {
    score := FLOAT_from_real(0.0);
    return;
  }

  norm_emb := sqrt_real(norm_emb);
  norm_query := sqrt_real(norm_query);

  if (norm_emb == 0.0 || norm_query == 0.0) {
    score := FLOAT_from_real(0.0);
    return;
  }

  var result: real := dot_prod / (norm_emb * norm_query);
  score := FLOAT_from_real(clamp_real(result, -1.0, 1.0));
}

method Ranker_dotProductScore(embedding: Ref, query_emb: Ref) returns (score: FLOAT)
  requires valid_tensor(embedding)
  requires valid_tensor(query_emb)
  ensures valid_float_slice(score)
{
  if (len(embedding.shape) != len(query_emb.shape)) {
    score := FLOAT_from_real(0.0);
    return;
  }

  var shape_match: bool := true;
  var i: int := 0;
  while (i < len(embedding.shape))
    invariant 0 <= i && i <= len(embedding.shape)
  {
    if (embedding.shape[i] != query_emb.shape[i]) {
      shape_match := false;
    }
    i := i + 1;
  }

  if (!shape_match) {
     score := FLOAT_from_real(0.0);
     return;
  }

  if (len(embedding.data) == 0) {
    score := FLOAT_from_real(0.0);
    return;
  }

  var dot_prod: real := 0.0;
  i := 0;
  while (i < len(embedding.data))
    invariant 0 <= i && i <= len(embedding.data)
  {
    var e: FLOAT := embedding.data[i];
    var q: FLOAT := query_emb.data[i];
    if (!FLOAT_is_nan(e) && !FLOAT_is_nan(q) && !FLOAT_is_inf(e) && !FLOAT_is_inf(q)) {
      dot_prod := dot_prod + FLOAT_value(e) * FLOAT_value(q);
    }
    i := i + 1;
  }
  score := FLOAT_from_real(dot_prod);
}

method Ranker_weightedAverage(scores: Seq[FLOAT], weights: Seq[FLOAT]) returns (avg: FLOAT)
  requires valid_float_slice(scores)
  requires valid_float_slice(weights)
  ensures valid_float_slice(avg)
{
  if (len(scores) != len(weights)) {
    avg := FLOAT_from_real(0.0);
    return;
  }
  if (len(scores) == 0) {
    avg := FLOAT_from_real(0.0);
    return;
  }

  var num: real := 0.0;
  var den: real := 0.0;
  var i: int := 0;
  while (i < len(scores))
    invariant 0 <= i && i <= len(scores)
  {
    var s: FLOAT := scores[i];
    var w: FLOAT := weights[i];
    if (!FLOAT_is_nan(s) && !FLOAT_is_nan(w) && !FLOAT_is_inf(s) && !FLOAT_is_inf(w)) {
      num := num + FLOAT_value(s) * FLOAT_value(w);
      den := den + FLOAT_value(w);
    }
    i := i + 1;
  }

  if (den == 0.0) {
    avg := FLOAT_from_real(0.0);
    return;
  }
  avg := FLOAT_from_real(num / den);
}

method Ranker_exponentialDecay(scores: Seq[FLOAT], decay_factor: FLOAT)
  requires valid_float_slice(scores)
{
  if (len(scores) == 0) { return; }
  if (FLOAT_value(decay_factor) <= 0.0 || FLOAT_value(decay_factor) >= 1.0) { return; }

  var current_decay: real := 1.0;
  var i: int := 0;
  while (i < len(scores))
    invariant 0 <= i && i <= len(scores)
  {
    if (!FLOAT_is_nan(scores[i]) && !FLOAT_is_inf(scores[i])) {
      scores[i] := FLOAT_from_real(FLOAT_value(scores[i]) * current_decay);
    }
    current_decay := current_decay * FLOAT_value(decay_factor);
    i := i + 1;
  }
}

method Ranker_normalizeScores(self: Ref, scores: Seq[FLOAT])
  requires valid_ranker(self)
  requires valid_float_slice(scores)
{
  normalizeScoresStatic(scores);
}

method Ranker_batchScore(self: Ref, sequences: Seq[Seq[UINT32]], ssi: Ref, allocator: Ref) returns (scores: Seq[FLOAT])
  requires valid_ranker(self)
  requires valid_ssi(ssi)
  requires valid_allocator(allocator)
  ensures valid_float_slice(scores)
  ensures len(scores) == len(sequences)
{
  if (len(sequences) == 0) {
    scores := alloc_f32(allocator, 0);
    return;
  }

  scores := alloc_f32(allocator, len(sequences));

  var b: int := 0;
  while (b < len(sequences))
    invariant 0 <= b && b <= len(sequences)
    invariant valid_float_slice(scores)
    invariant len(scores) == len(sequences)
  {
    scores[b] := Ranker_scoreSequence(self, sequences[b], ssi);
    b := b + 1;
  }
}

method Ranker_topKHeap(self: Ref, ssi: Ref, query: Seq[UINT32], k: int, allocator: Ref) returns (top_k: Seq[Ref])
  requires valid_ranker(self)
  requires valid_ssi(ssi)
  requires valid_u32_slice(query)
  requires valid_allocator(allocator)
  ensures forall i: int :: 0 <= i && i < len(top_k) ==> valid_ranked_segment_write(top_k[i])
{
  if (k == 0) {
    top_k := alloc_ranked_segment_array(allocator, 0);
    return;
  }

  var heap: Seq[Ref] := alloc_ranked_segment_array(allocator, 0);

  var candidates: Seq[Ref] := ssi_retrieveTopK(ssi, query, RANKERCONFIG_DEFAULT_TOP_K_RETRIEVAL, allocator);

  var i: int := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
  {
    var cand: Ref := candidates[i];
    var score_val: FLOAT := Ranker_scoreSequenceWithQuery(self, cand.tokens, query, ssi);

    if (FLOAT_is_nan(score_val) || FLOAT_is_inf(score_val)) {
      i := i + 1;
      continue;
    }

    if (len(heap) < k) {
      var ranked: Ref := RankedSegment_init(allocator, cand.tokens, score_val, cand.position, cand.anchor);
      heap := heap + seq(1, ranked);
    } else {
      var min_idx: int := 0;
      var min_s: FLOAT := heap[0].score;
      var j: int := 1;
      while (j < len(heap))
        invariant 0 <= j && j <= len(heap)
      {
        if (FLOAT_value(heap[j].score) < FLOAT_value(min_s)) {
          min_s := heap[j].score;
          min_idx := j;
        }
        j := j + 1;
      }

      if (FLOAT_value(score_val) > FLOAT_value(min_s)) {
        RankedSegment_deinit(allocator, heap[min_idx]);
        var ranked: Ref := RankedSegment_init(allocator, cand.tokens, score_val, cand.position, cand.anchor);
        heap[min_idx] := ranked;
      }
    }
    i := i + 1;
  }

  top_k := alloc_ranked_segment_array(allocator, len(heap));
  var idx: int := len(heap) - 1;
  while (idx >= 0)
    invariant -1 <= idx && idx < len(heap)
  {
    top_k[idx] := heap[idx];
    idx := idx - 1;
  }
}

method Ranker_parallelScore(self: Ref, sequences: Seq[Seq[UINT32]], ssi: Ref, num_threads: int) returns (scores: Seq[FLOAT])
  requires valid_ranker(self)
  requires valid_ssi(ssi)
  ensures valid_float_slice(scores)
  ensures len(scores) == len(sequences)
{
  if (len(sequences) == 0) {
    scores := alloc_f32(self.allocator, 0);
    return;
  }

  scores := alloc_f32(self.allocator, len(sequences));
  var i: int := 0;
  while (i < len(sequences))
    invariant 0 <= i && i <= len(sequences)
    invariant valid_float_slice(scores)
  {
    scores[i] := Ranker_scoreSequence(self, sequences[i], ssi);
    i := i + 1;
  }
}

method Ranker_calibrateWeights(self: Ref, training_data: Seq[Seq[UINT32]], labels: Seq[FLOAT], ssi: Ref, epochs: int)
  requires valid_ranker_write(self)
  requires valid_ssi(ssi)
  requires valid_float_slice(labels)
  requires len(training_data) == len(labels)
{
  if (len(training_data) == 0 || len(labels) == 0) { return; }

  var gradients: Seq[FLOAT] := alloc_f32(self.allocator, len(self.ngram_weights));

  var epoch: int := 0;
  while (epoch < epochs)
    invariant 0 <= epoch && epoch <= epochs
    invariant valid_float_slice(gradients)
  {
    var g: int := 0;
    while (g < len(gradients))
      invariant 0 <= g && g <= len(gradients)
    {
      gradients[g] := FLOAT_from_real(0.0);
      g := g + 1;
    }

    var i: int := 0;
    while (i < len(training_data))
      invariant 0 <= i && i <= len(training_data)
    {
      var pred: FLOAT := Ranker_scoreSequence(self, training_data[i], ssi);
      var label: FLOAT := labels[i];

      if (!FLOAT_is_nan(pred) && !FLOAT_is_nan(label) && !FLOAT_is_inf(pred) && !FLOAT_is_inf(label)) {
        var err: real := FLOAT_value(pred) - FLOAT_value(label);
        var g2: int := 0;
        while (g2 < len(gradients))
          invariant 0 <= g2 && g2 <= len(gradients)
        {
          gradients[g2] := FLOAT_from_real(FLOAT_value(gradients[g2]) + err * FLOAT_value(RANKERCONFIG_LEARNING_RATE));
          g2 := g2 + 1;
        }
      }
      i := i + 1;
    }
    Ranker_updateWeights(self, gradients);
    epoch := epoch + 1;
  }

  free_f32(self.allocator, gradients);
}

method Ranker_rankCandidatesWithQuery(self: Ref, candidates: Seq[Ref], query: Seq[UINT32], ssi: Ref, allocator: Ref)
  requires valid_ranker(self)
  requires forall i: int :: 0 <= i && i < len(candidates) ==> valid_ranked_segment_write(candidates[i])
  requires valid_u32_slice(query)
  requires valid_ssi(ssi)
  requires valid_allocator(allocator)
{
  if (len(candidates) == 0) { return; }

  var scores: Seq[FLOAT] := alloc_f32(allocator, len(candidates));

  var i: int := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
    invariant valid_float_slice(scores)
  {
    scores[i] := Ranker_scoreSequenceWithQuery(self, candidates[i].tokens, query, ssi);
    i := i + 1;
  }

  normalizeScoresStatic(scores);

  var indices: Seq[int] := alloc_int(allocator, len(candidates));
  i := 0;
  while (i < len(indices))
    invariant 0 <= i && i <= len(indices)
  {
    indices[i] := i;
    i := i + 1;
  }

  indices := sort_indices(indices, scores);

  var sorted_tokens: Seq[Seq[UINT32]] := alloc_u32_array(allocator, len(candidates));
  var sorted_scores: Seq[FLOAT] := alloc_f32(allocator, len(candidates));
  var sorted_positions: Seq[UINT64] := alloc_u64(allocator, len(candidates));
  var sorted_anchors: Seq[bool] := alloc_bool_array(allocator, len(candidates));

  i := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
  {
    var src_idx: int := indices[i];
    sorted_tokens[i] := dupe_u32(allocator, candidates[src_idx].tokens);
    sorted_scores[i] := scores[src_idx];
    sorted_positions[i] := candidates[src_idx].position;
    sorted_anchors[i] := candidates[src_idx].anchor;
    i := i + 1;
  }

  i := 0;
  while (i < len(candidates))
    invariant 0 <= i && i <= len(candidates)
  {
    free_u32(allocator, candidates[i].tokens);
    candidates[i].tokens := sorted_tokens[i];
    candidates[i].score := sorted_scores[i];
    candidates[i].position := sorted_positions[i];
    candidates[i].anchor := sorted_anchors[i];
    i := i + 1;
  }

  free_f32(allocator, scores);
  free_int(allocator, indices);
}

method Ranker_rankByMultipleCriteria(self: Ref, candidates: Seq[Ref], criteria: Seq[Seq[FLOAT]], weights: Seq[FLOAT], allocator: Ref)
  requires valid_ranker(self)
  requires forall i: int :: 0 <= i && i < len(candidates) ==> valid_ranked_segment_write(candidates[i])
  requires forall i: int :: 0 <= i && i < len(criteria) ==> valid_float_slice(criteria[i])
  requires valid_float_slice(weights)
  requires valid_allocator(allocator)
{
  if (len(candidates) == 0) { return; }
  if (len(criteria) == 0) { return; }
  if (len(weights) == 0) { return; }

  var num_cand: int := len(candidates);
  var num_crit: int := min(len(criteria), len(weights));

  var combined: Seq[FLOAT] := alloc_f32(allocator, num_cand);

  var c: int := 0;
  while (c < num_cand)
    invariant 0 <= c && c <= num_cand
    invariant valid_float_slice(combined)
  {
    var crit_score: real := 0.0;
    var cr: int := 0;
    while (cr < num_crit)
      invariant 0 <= cr && cr <= num_crit
    {
      if (c < len(criteria[cr])) {
        var score_val: FLOAT := criteria[cr][c];
        var weight_val: FLOAT := weights[cr];
        if (!FLOAT_is_nan(score_val) && !FLOAT_is_nan(weight_val) && !FLOAT_is_inf(score_val) && !FLOAT_is_inf(weight_val)) {
          crit_score := crit_score + FLOAT_value(score_val) * FLOAT_value(weight_val);
        }
      }
      cr := cr + 1;
    }
    combined[c] := FLOAT_from_real(crit_score);
    c := c + 1;
  }

  var indices: Seq[int] := alloc_int(allocator, num_cand);
  var i: int := 0;
  while (i < num_cand)
    invariant 0 <= i && i <= num_cand
  {
    indices[i] := i;
    i := i + 1;
  }

  indices := sort_indices(indices, combined);

  var sorted_tokens: Seq[Seq[UINT32]] := alloc_u32_array(allocator, num_cand);
  var sorted_scores: Seq[FLOAT] := alloc_f32(allocator, num_cand);
  var sorted_positions: Seq[UINT64] := alloc_u64(allocator, num_cand);
  var sorted_anchors: Seq[bool] := alloc_bool_array(allocator, num_cand);

  i := 0;
  while (i < num_cand)
    invariant 0 <= i && i <= num_cand)
  {
    var src_idx: int := indices[i];
    sorted_tokens[i] := dupe_u32(allocator, candidates[src_idx].tokens);
    sorted_scores[i] := combined[src_idx];
    sorted_positions[i] := candidates[src_idx].position;
    sorted_anchors[i] := candidates[src_idx].anchor;
    i := i + 1;
  }

  i := 0;
  while (i < num_cand)
    invariant 0 <= i && i <= num_cand
  {
    free_u32(allocator, candidates[i].tokens);
    candidates[i].tokens := sorted_tokens[i];
    candidates[i].score := sorted_scores[i];
    candidates[i].position := sorted_positions[i];
    candidates[i].anchor := sorted_anchors[i];
    i := i + 1;
  }

  free_f32(allocator, combined);
  free_int(allocator, indices);
}

entries.query:
domain FLOAT {
  function real value(f: FLOAT): real
  function FLOAT from_real(r: real): FLOAT
  function real sqrt_real(r: real): real
  function real clamp_real(r: real, min: real, max: real): real
  function real f32_to_real(f: FLOAT): real
  function FLOAT real_to_f32(r: real): FLOAT
  function bool is_nan(f: FLOAT): bool
  function bool is_inf(f: FLOAT): bool
}

domain UINT64 {
  function int value(u: UINT64): int
  function UINT64 from_int(i: int): UINT64
  function UINT64 xor(a: UINT64, b: UINT64): UINT64
  function UINT64 mul(a: UINT64, b: UINT64): UINT64
  function UINT64 add(a: UINT64, b: UINT64): UINT64
  function UINT64 min(a: UINT64, b: UINT64): UINT64
  function int popcount(a: UINT64): int
  function int clamped_to_int(u: UINT64): int
}

domain UINT32 {
  function int value(u: UINT32): int
  function UINT32 from_int(i: int): UINT32
}

domain USIZE {
  function int value(u: USIZE): int
  function USIZE from_int(i: int): USIZE
}

function stableHash(data: Seq[int], seed: UINT64): UINT64

domain RANKERCONFIG {
  const STREAMING_BUFFER_SIZE: int
  const STREAMING_WINDOW_SIZE: int
  const DEFAULT_TOP_K_RETRIEVAL: int
  const HASH_SEED_MULTIPLIER_A: UINT64
  const HASH_SEED_MULTIPLIER_B: UINT64
  const LEARNING_RATE: FLOAT
  const DIVERSITY_WEIGHT: FLOAT
  const PROXIMITY_WEIGHT: FLOAT
  const MAX_RAW_SCORE: FLOAT
  const BASE_SCORE_WEIGHT: FLOAT
  const OVERLAP_WEIGHT: FLOAT
  const JACCARD_WEIGHT: FLOAT
}

field ngram_weights: Seq[FLOAT]
field lsh_hash_params: Seq[UINT64]
field num_hash_functions: int
field num_ngrams: int
field seed: UINT64
field allocator: Ref
